mapper.select:
SELECT stat_date, SUM(created_count) AS created_count, SUM(completed_count) AS completed_count
FROM (
    SELECT DATE(created_at) AS stat_date, COUNT(*) AS created_count, 0 AS completed_count
    FROM work_orders
    WHERE tenant_id = #{tenantId}
      AND created_at >= #{startTime} AND created_at < #{endTime}
    GROUP BY DATE(created_at)
    UNION ALL
    SELECT DATE(completed_at) AS stat_date, 0 AS created_count, COUNT(*) AS completed_count
    FROM work_orders
    WHERE tenant_id = #{tenantId}
      AND completed_at >= #{startTime} AND completed_at < #{endTime}
    GROUP BY DATE(completed_at)
) daily_counts
GROUP BY stat_date
ORDER BY stat_date ASC
